static void pd_poll_timer_cb(lv_timer_t *timer)
{
    int8_t result;

    (void)timer;

    if (!s_pd_waiting)
    {
        return;
    }

    result = MsgQueueGet_PD_ready();

    if (result == 0)
    {
        return;
    }

    s_pd_waiting = false;
    pd_box_hide();

    if (result == 1)
    {
        lv_lib_pm_goto("PPS Page", 0U);
    }
    else if (result == 2)
    {
        lv_lib_pm_goto("PDFixed Page", 0U);
    }
    else
    {
        /*
         * STEP9修复说明：协商失败时PD任务已经主动关闭CC；
         * UI再发送一次STOP用于统一收尾。STOP设计为幂等操作，重复执行不会重启协商。
         */
        (void)ui_send_pdsink_stop_msg();
        pd_box_show_fail();
    }
}

static void _set_range_label_text(uint8_t mode)
{
    if (mode == GATE_MODE_AUTO) {
        lv_label_set_text(ui_LabelRangeMode, _("AUTO"));
    } else if (mode == GATE_MODE_LOW) {
        lv_label_set_text(ui_LabelRangeMode, _("LOW"));
    } else if (mode == GATE_MODE_MID) {
        lv_label_set_text(ui_LabelRangeMode, _("MID"));
    } else {
        lv_label_set_text(ui_LabelRangeMode, _("HIGH"));
    }
}

///////////////// key function ///////////////////
void ui_set_page_key_handler(void *key_event)
{
    key_event_t *event = (key_event_t *)key_event;
    const int panel_count = (int)(sizeof(panels) / sizeof(panels[0]));

    if (event == NULL)
    {
        return;
    }

    /*
     * 正在协商时锁住其他操作。
     * 仍然允许按B取消协商。
     */
    if (s_pd_waiting)
    {
        if (event->id == KEY_ID_B &&
            event->type == KEY_EVT_CLICK)
        {
            (void)ui_send_pdsink_stop_msg();
            s_pd_waiting = false;
            lv_obj_clear_state(ui_SwitchPD, LV_STATE_CHECKED);
            pd_box_hide();
        }

        return;
    }

    /*
     * 失败提示框显示期间，按B只关闭提示框，
     * 不直接退出设置页。
     */
    if (s_pd_box != NULL)
    {
        if (event->id == KEY_ID_B &&
            event->type == KEY_EVT_CLICK)
        {
            pd_box_hide();
        }

        return;
    }

    if (event->id == KEY_ID_B && event->type == KEY_EVT_CLICK)
    {
        if (s_settings_dirty)
        {
            (void)ui_system_settings_save();
            s_settings_dirty = false;
        }
        lv_lib_pm_goto_first();
        return;
    }

    if (event->id == KEY_ID_L && event->type == KEY_EVT_CLICK)
    {
        lv_obj_clear_state(panels[current_panel_index], LV_STATE_CHECKED);
        current_panel_index = (current_panel_index - 1 + panel_count) % panel_count;
        lv_obj_add_state(panels[current_panel_index], LV_STATE_CHECKED);
        lv_obj_scroll_to_view(panels[current_panel_index], LV_ANIM_ON);
        return;
    }

    if (event->id == KEY_ID_R && event->type == KEY_EVT_CLICK)
    {
        lv_obj_clear_state(panels[current_panel_index], LV_STATE_CHECKED);
        current_panel_index = (current_panel_index + 1) % panel_count;
        lv_obj_add_state(panels[current_panel_index], LV_STATE_CHECKED);
        lv_obj_scroll_to_view(panels[current_panel_index], LV_ANIM_ON);
        return;
    }

    if (event->id != KEY_ID_Y && event->id != KEY_ID_N)
    {
        return;
    }

    switch (current_panel_index)
    {
        case 0:
            if (event->type == KEY_EVT_CLICK || event->type == KEY_EVT_REPEAT)
            {
                int16_t value = lv_slider_get_value(ui_SliderBL);
                value += (event->id == KEY_ID_Y) ? 10 : -10;
                if (value > 100) value = 100;
                if (value < 10) value = 10;
                lv_slider_set_value(ui_SliderBL, value, LV_ANIM_ON);
                ui_set_back_light_level((uint8_t)value);
                s_settings_dirty = true;
            }
            break;

        case 1:
            if (event->type == KEY_EVT_CLICK)
            {
                const bool enable = event->id == KEY_ID_Y;
                if (enable) lv_obj_add_state(ui_SwitchKS, LV_STATE_CHECKED);
                else lv_obj_clear_state(ui_SwitchKS, LV_STATE_CHECKED);
                ui_set_key_sound_enable(enable);
                s_settings_dirty = true;
            }
            break;

        case 2:
            if (event->type == KEY_EVT_CLICK)
            {
                const bool chinese = event->id == KEY_ID_Y;
                if (chinese) lv_obj_add_state(ui_SwitchLang, LV_STATE_CHECKED);
                else lv_obj_clear_state(ui_SwitchLang, LV_STATE_CHECKED);
                ui_set_language_select(chinese ? 1U : 0U);
                (void)lv_i18n_set_locale(chinese ? "zh-cn" : "en");
                s_settings_dirty = true;
                show_restart_msgbox();
            }
            break;

        case 3:
            if (event->type == KEY_EVT_CLICK)
            {
                uint16_t rotation = ui_get_display_rotation();
                rotation = (event->id == KEY_ID_Y)
                         ? (uint16_t)((rotation + 90U) % 360U)
                         : (uint16_t)((rotation + 270U) % 360U);
                ui_set_display_rotation(rotation);
                if (rotation == 0U) lv_label_set_text(ui_LabelRotNum, "<  0  >");
                else if (rotation == 90U) lv_label_set_text(ui_LabelRotNum, "< 90 >");
                else if (rotation == 180U) lv_label_set_text(ui_LabelRotNum, "< 180 >");
                else lv_label_set_text(ui_LabelRotNum, "< 270 >");
                s_settings_dirty = true;
                ui_full_screen_refresh(ui_SetPage);
            }
            break;

        case 4:
            if (event->type == KEY_EVT_CLICK)
            {
                uint8_t mode = ui_get_current_range_mode();
                mode = (event->id == KEY_ID_Y)
                     ? (uint8_t)((mode + 1U) % 4U)
                     : (uint8_t)((mode + 3U) % 4U);
                ui_set_current_range_mode(mode);
                _set_range_label_text(mode);
                s_settings_dirty = true;
            }
            break;


        case 5:
            if (event->id == KEY_ID_Y &&
                event->type == KEY_EVT_CLICK)
            {
                /*
                 * 清理可能残留的上一轮结果。
                 */
                while (MsgQueueGet_PD_ready() != 0)
                {
                }

                if (ui_send_pdsink_start_msg())
                {
                    pd_box_show_wait();
                }
                else
                {
                    pd_box_show_fail();
                }
            }
            break;

        case 6:
            // About面板不处理按键
            break;


        default:
            break;
    }
}

