// 显示重启提示弹窗
static void show_restart_msgbox(void)
{
    int32_t view_y = lv_obj_get_scroll_top(ui_SetPage);

    if (s_restart_timer != NULL)
    {
        lv_timer_delete(s_restart_timer);
        s_restart_timer = NULL;
    }
    if (s_restart_msgbox != NULL)
    {
        lv_obj_delete(s_restart_msgbox);
    }

    s_restart_msgbox = lv_obj_create(ui_SetPage);
    lv_obj_set_size(s_restart_msgbox, 220, 100);
    lv_obj_center(s_restart_msgbox);
    lv_obj_set_pos(s_restart_msgbox, 0, view_y);
    lv_obj_set_style_bg_color(s_restart_msgbox, lv_color_hex(0x958030), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(s_restart_msgbox, 200, LV_PART_MAIN | LV_STATE_DEFAULT);

    // 添加文本
    lv_obj_t * label = lv_label_create(s_restart_msgbox);
    lv_label_set_text(label, _("Please reboot to apply\nall changes!"));
    lv_obj_center(label);
    if(ui_get_language_select() == 0)
    {
        // 如果是English
        lv_obj_set_style_text_font(label, &lv_font_montserrat_18, LV_PART_MAIN | LV_STATE_DEFAULT);
    }
    else
    {
        // 如果是中文
        lv_obj_set_style_text_font(label, &ui_font_zhongyuan20, LV_PART_MAIN | LV_STATE_DEFAULT);
    }
    lv_obj_set_style_text_align(label, LV_TEXT_ALIGN_CENTER, 0);

    s_restart_timer = lv_timer_create(restart_msgbox_timer_cb, 2000U, NULL);
}

